python3 << 'EOF'
import json

# Load data for pass-through fix
with open('/app/output/subsidy_yearly.json') as f:
    subsidy_yearly = json.load(f)

# Compute exact 2020 and 2022 values
pt = {}
for row in subsidy_yearly:
    if row['year'] == 2020:
        pt[row['subsidy_level']] = {'y2020': row['petrol_usd_liter']}
    if row['year'] == 2022:
        pt[row['subsidy_level']] = pt.get(row['subsidy_level'], {})
        pt[row['subsidy_level']]['y2022'] = row['petrol_usd_liter']

for k,v in pt.items():
    if 'y2020' in v and 'y2022' in v and v['y2020'] != 0:
        v['change'] = round(((v['y2022'] - v['y2020']) / v['y2020']) * 100, 1)
    else:
        v['change'] = None

with open('/app/output/pass_through_exact.json','w') as f:
    json.dump(pt, f, indent=2)
print(pt)
EOF
